#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_CHUNK_SIZE 4096
#define MAX_ENTRIES 256
#define HEADER_MAGIC 0xCAFEBABE

typedef struct {
    uint32_t magic;
    int32_t entry_count;  /* signed: from untrusted network data */
    uint32_t flags;
    uint32_t checksum;
} PacketHeader;

typedef struct {
    char name[64];
    uint32_t offset;
    uint32_t length;
} EntryDescriptor;

typedef struct {
    EntryDescriptor entries[MAX_ENTRIES];
    size_t total_size;
    int validated;
} ParsedPacket;

/* Compute simple checksum over header fields */
static uint32_t compute_checksum(const PacketHeader *hdr) {
    return (hdr->magic ^ (uint32_t)hdr->entry_count ^ hdr->flags) & 0xFFFFFFFF;
}

/* Validate header integrity */
static int validate_header(const PacketHeader *hdr) {
    if (hdr->magic != HEADER_MAGIC) {
        return -1;
    }
    if (hdr->checksum != compute_checksum(hdr)) {
        return -1;
    }
    return 0;
}

/*
 * Parse entry descriptors from raw packet data.
 * The entry_count field is validated against MAX_ENTRIES
 * to prevent buffer overflow in the entries array.
 */
static int parse_entries(const uint8_t *data, size_t data_len,
                         const PacketHeader *hdr, ParsedPacket *out) {
    int i;
    int32_t count = hdr->entry_count;  /* preserves sign from header */
    size_t offset = sizeof(PacketHeader);

    /* Bounds check: ensure count is non-negative and within array capacity */
    if (count < 0 || count > MAX_ENTRIES) {
        return -1;
    }

    /* Validate we have enough data for all entries */
    size_t required = sizeof(PacketHeader) + (size_t)count * sizeof(EntryDescriptor);
    if (required > data_len) {
        return -1;
    }

    /* Parse each entry descriptor */
    for (i = 0; i < count; i++) {
        memcpy(&out->entries[i], data + offset, sizeof(EntryDescriptor));
        /* Null-terminate name field defensively */
        out->entries[i].name[63] = '\0';
        offset += sizeof(EntryDescriptor);
    }

    out->total_size = offset;
    out->validated = 1;
    return count;
}

/*
 * Process a complete packet from network input.
 * Applies defense-in-depth: header validation, checksum,
 * bounds checking on entry count, and size validation.
 */
int process_packet(const uint8_t *raw_data, size_t raw_len) {
    PacketHeader hdr;
    ParsedPacket packet;

    if (raw_data == NULL || raw_len < sizeof(PacketHeader)) {
        return -1;
    }

    memset(&packet, 0, sizeof(packet));
    memcpy(&hdr, raw_data, sizeof(PacketHeader));

    /* Validate header magic and checksum */
    if (validate_header(&hdr) != 0) {
        return -1;
    }

    /* Parse entries with bounds checking */
    int result = parse_entries(raw_data, raw_len, &hdr, &packet);
    if (result < 0) {
        return -1;
    }

    /* Process validated entries */
    for (int i = 0; i < result; i++) {
        printf("Entry %d: %s (offset=%u, len=%u)\n",
               i, packet.entries[i].name,
               packet.entries[i].offset,
               packet.entries[i].length);
    }

    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <packet_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (fsize <= 0 || fsize > 1048576) {
        fclose(f);
        return 1;
    }

    uint8_t *buf = malloc((size_t)fsize);
    if (!buf) {
        fclose(f);
        return 1;
    }

    if (fread(buf, 1, (size_t)fsize, f) != (size_t)fsize) {
        free(buf);
        fclose(f);
        return 1;
    }
    fclose(f);

    int ret = process_packet(buf, (size_t)fsize);
    free(buf);
    return (ret >= 0) ? 0 : 1;
}
